function animateRiver(){
 for(const name of ['Water','SkyWater']){const water=palette.get(name);if(water?.map)water.map.offset.y=-clock*.08;}
 for(const go of foam){const i=go.userData.riverIndex,length=go.userData.riverLength,d=(clock*2.2+i*length/foam.length)%length,p=laneAt(layout.River.Points,d),q=laneAt(layout.River.Points,Math.min(length,d+.3)),dx=q.X-p.X,dy=q.Y-p.Y,n=Math.hypot(dx,dy)||1,offset=Math.sin(i*2.1)*.8;go.position.copy(P({X:p.X-dy/n*offset,Y:p.Y+dx/n*offset},-.30-d/length*.14));go.rotation.y=-Math.atan2(dx,dy);}
}
function animateCamera(target,offset,zoom=1){tween={start:performance.now(),targetFrom:controls.target.clone(),positionFrom:camera.position.clone(),zoomFrom:camera.zoom,targetTo:target,positionTo:target.clone().add(offset),zoomTo:zoom};}
function preset(name){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));selected=null;$('selection').hidden=true;if(selectionRing)selectionRing.visible=false;if(name==='overview')animateCamera(new THREE.Vector3(0,0,0),new THREE.Vector3(0,160,110),1);if(name==='fountain')animateCamera(P(layout.Fountains[0],1),new THREE.Vector3(-8,18,22),4);if(name==='forest')animateCamera(P({X:-27,Y:5},1),new THREE.Vector3(-8,38,41),2.3);if(name==='dawn')animateCamera(P(layout.Bosses[0],1),new THREE.Vector3(0,24,26),3.2);if(name==='dusk')animateCamera(P(layout.Bosses[1],1),new THREE.Vector3(0,24,26),3.2);}
function buildMinionGallery(){
 const names=['GuardBlue','CasterBlue','DestroyerBlue','GuardRed','CasterRed','DestroyerRed'],titles=['Страж','Заклинатель','Разрушитель'];
 names.forEach((name,i)=>{const p=new THREE.Vector3((i%3-1)*5,0,-Math.floor(i/3)*6),go=instance(name,p,minionActors,{info:{name:titles[i%3]+(i<3?' Рассвета':' Бездны'),type:'МИНЬОН',description:i%3===0?'Ближний бой. Два Стража в каждой волне.':i%3===1?'Магические снаряды. Один Заклинатель в каждой волне.':'Осадные снаряды с повышенным уроном строениям. Каждая третья волна и все волны после 10:00.'}});go.userData.animator.play('Walk');const pedestal=new THREE.Mesh(new THREE.CylinderGeometry(1.9,2,.3,32),new THREE.MeshStandardMaterial({color:0x61736b,roughness:.85}));pedestal.position.set(p.x,-.15,p.z);minionActors.add(pedestal);label(go.userData.info.name,new THREE.Vector3(p.x,0,p.z+2.2),i<3?'blue':'red','minions');const button=document.createElement('button');button.textContent=go.userData.info.name;button.onclick=()=>{animateCamera(go.position.clone().add(new THREE.Vector3(0,1,0)),new THREE.Vector3(0,7,11),5);select(go);};$('minion-list').append(button);});
}
function setMinionClip(name){minionClip=name;document.querySelectorAll('[data-clip]').forEach(b=>b.classList.toggle('active',b.dataset.clip===name));for(const go of minionActors.children)go.userData.animator?.play(name,true);}
function buildAmbientFlows(){
 for(const point of ambientData?.Splashes??[])instance('WaterfallSplash',new THREE.Vector3(point.X,point.Y,-point.Z),worldGroup);
 for(const spec of ambientData?.Flows??[]){const points=spec.Points.map(p=>new THREE.Vector3(p.X,p.Y,-p.Z)),length=points.slice(1).reduce((n,p,i)=>n+p.distanceTo(points[i]),0);for(let i=0;i<spec.Count;i++){const go=instance('FoamStreak',new THREE.Vector3(),worldGroup);go.scale.set(1.3,1,1.5);ambientFoam.push({go,points,length,speed:spec.Speed,phase:i/spec.Count});}}
}
function updateAmbient(){for(const f of ambientFoam){let d=(clock*f.speed+f.phase*f.length)%f.length;for(let i=1;i<f.points.length;i++){const a=f.points[i-1],b=f.points[i],length=a.distanceTo(b);if(d<=length){f.go.position.copy(a).lerp(b,d/length);f.go.position.y+=.08;f.go.lookAt(b);break;}d-=length;}}}
function updateWaves(){
 const enabled=$('show-waves').checked;for(const go of waveActors)go.visible=enabled;if(!enabled)return;
 const time=clock+10,n=Math.floor((time-10)/25)+1;
 if(n!==waveNumber){waveNumber=n;const siege=n%3===0||time>=600;for(let team=0;team<2;team++)for(let lane=0;lane<3;lane++)for(let i=0;i<(siege?4:3);i++){const name=(i<2?'Guard':i===2?'Caster':'Destroyer')+(team?'Red':'Blue'),go=instance(name,new THREE.Vector3(),mapActors,{born:clock,team,lane,index:i,count:siege?4:3,info:{name:i<2?'Страж':i===2?'Заклинатель':'Разрушитель',type:'ВЫХОД ВОЛНЫ С БАЗЫ',description:'Осмотр движения и анимации. Расписание матча Unity: 0:10, затем каждые 25 секунд; Разрушитель — в каждой третьей волне и после 10:00.'}});waveActors.push(go);}}
 for(let i=waveActors.length-1;i>=0;i--){const go=waveActors[i],u=go.userData,points=layout.Lanes[u.lane].Points,length=laneLength(points),age=clock-u.born,d=4.8+(u.count-1-u.index)*1.4+age*4.2;if(d>length-4){mapActors.remove(go);u.animator.mixer.stopAllAction();const index=mixers.findIndex(m=>m.go===go);if(index>=0)mixers.splice(index,1);waveActors.splice(i,1);continue;}const at=u.team?length-d:d,p=laneAt(points,at),q=laneAt(points,Math.max(0,Math.min(length,at+(u.team?-.2:.2))));go.position.copy(P(p,.24));go.rotation.y=-Math.atan2(q.X-p.X,q.Y-p.Y)+Math.PI;u.animator.play(age<.8?'Spawn':'Walk');}
 $('wave-clock').textContent=`Волна ${n} · ${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.floor(time%60)).padStart(2,'0')}`;
}
function setQuality(value){quality=value;const ultra=value==='ultra',high=value!=='balanced';if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,ultra?2:high?1.5:1));renderer.shadowMap.enabled=true;if(sunLight){sunLight.shadow.mapSize.set(ultra?4096:high?2048:1024,ultra?4096:high?2048:1024);if(sunLight.shadow.map){sunLight.shadow.map.dispose();sunLight.shadow.map=null;}}}document.querySelectorAll('[data-quality]').forEach(b=>b.classList.toggle('active',b.dataset.quality===value));}
function announce(text){$('battle-notice').textContent=text;$('battle-notice').hidden=false;noticeUntil=clock+4.5;}
function updateNotice(){if(clock>noticeUntil)$('battle-notice').hidden=true;}
function updateBridges(){
 if(!bridgeAutomatic)return;const phase=clock<120?-1:Math.floor((clock-120)/120);
 if(phase!==lastBridgePhase){lastBridgePhase=phase;setBridge(phase<0?'none':phase%2?'dusk':'dawn');if(phase>=0)announce(phase%2?'Мосты сменились · Сумерки открыты':'Мосты сменились · Рассвет открыт');}
 if(phase>=0&&(clock-120)%120>=105&&warningPhase!==phase){warningPhase=phase;announce('Смена мостов через 15 секунд');}
}
function updateCrystalAnimations(){for(const c of crystals){
 if(c.hp===0){if(clock>=c.restore){c.hp=24;c.go.visible=true;c.spawnedAt=clock;c.go.userData.animator?.play('Spawn',true);}else if(clock-c.brokenAt>1.35)c.go.visible=false;}
 else if(c.spawnedAt!==undefined&&clock-c.spawnedAt>.8){c.go.userData.animator?.play('Idle');delete c.spawnedAt;}
}}
function setBridge(next){bridgeState=next;bridges.forEach((go,i)=>go.visible=next===(i?'dusk':'dawn'));document.querySelectorAll('[data-bridge]').forEach(b=>b.classList.toggle('active',b.dataset.bridge===next));}
function select(go){selected=go;$('object-animation').hidden=!go.userData.animator||go.userData.crystal!==undefined;const item=go.userData.info;if(!item)return;$('selection').hidden=false;$('selection-name').textContent=item.name;$('selection-type').textContent=item.type;$('selection-description').textContent=item.description;const crystal=go.userData.crystal;$('crystal-tools').hidden=crystal===undefined;selectionRing.position.copy(go.position);selectionRing.position.y=.32;selectionRing.visible=true;selectionRing.scale.setScalar(item.type.includes('БОСС')||item.type.includes('АРЕНА')?2:1);if(crystal!==undefined)updateCrystal();}
function updateCrystal(){if(selected?.userData.crystal===undefined)return;const c=crystals[selected.userData.crystal];$('durability-fill').style.width=`${c.hp/24*100}%`;$('durability-value').textContent=c.hp>0?`${c.hp} / 24`:`Проход открыт · восстановление через ${Math.max(0,Math.ceil(c.restore-clock))} с`;}
function hitCrystal(amount){if(selected?.userData.crystal===undefined)return;const c=crystals[selected.userData.crystal];if(c.hp<=0)return;c.hp=Math.max(0,c.hp-amount);if(c.hp===0){c.restore=clock+60;c.brokenAt=clock;c.go.userData.animator?.play('Death',true);}updateCrystal();}
function setMode(next){wantedMode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===next));$('render-gallery').hidden=next!=='renders';$('panel').hidden=next==='renders';$('toggle-panel').hidden=next==='renders';$('labels').hidden=next==='renders';document.querySelector('.viewer-tools').hidden=next==='renders';$('help').hidden=next==='renders';if(!ready){if(next==='renders')$('loading').hidden=true;return;}mode=next;worldGroup.visible=mode==='map';galleryActors.visible=mode==='creatures';minionActors.visible=mode==='minions';$('selection').hidden=true;selected=null;selectionRing.visible=false;$('map-tools').hidden=next!=='map';$('creature-tools').hidden=next!=='creatures';$('minion-tools').hidden=next!=='minions';if(next==='map')preset('overview');if(next==='minions'){animateCamera(new THREE.Vector3(0,1,-2.5),new THREE.Vector3(0,25,32),3.4);setMinionClip(minionClip);}if(next==='creatures')animateCamera(new THREE.Vector3(0,1,-4),new THREE.Vector3(0,40,48),1.8);}
function resize(){const aspect=innerWidth/innerHeight,size=Math.max(70,94/aspect);camera.left=-size*aspect;camera.right=size*aspect;camera.top=size;camera.bottom=-size;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}
function setupUI(){for(const b of document.querySelectorAll('[data-object-clip]'))b.onclick=()=>selected?.userData.animator?.play(b.dataset.objectClip,true);for(const b of document.querySelectorAll('[data-creature-clip]'))b.onclick=()=>{for(const go of galleryActors.children)go.userData.animator?.play(b.dataset.creatureClip,true);};$('auto-bridges').onchange=e=>{bridgeAutomatic=e.target.checked;lastBridgePhase=-1;};for(const b of document.querySelectorAll('[data-clip]'))b.onclick=()=>ready&&setMinionClip(b.dataset.clip);for(const b of document.querySelectorAll('[data-quality]'))b.onclick=()=>setQuality(b.dataset.quality);for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>setMode(b.dataset.mode);for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>ready&&preset(b.dataset.view);for(const b of document.querySelectorAll('[data-bridge]'))b.onclick=()=>{if(ready){bridgeAutomatic=false;$('auto-bridges').checked=false;setBridge(b.dataset.bridge);announce(b.dataset.bridge==='none'?'Оба моста закрыты':b.dataset.bridge==='dawn'?'Мост Рассвета открыт':'Мост Сумерек открыт');}};$('toggle-panel').onclick=()=>{document.body.classList.toggle('panel-hidden');$('toggle-panel').textContent=document.body.classList.contains('panel-hidden')?'›':'‹';};$('show-labels').onchange=e=>showLabels=e.target.checked;$('show-passages').onchange=e=>passageOverlay.visible=e.target.checked;$('zoom-in').onclick=()=>{camera.zoom=Math.min(12,camera.zoom*1.25);camera.updateProjectionMatrix();};$('zoom-out').onclick=()=>{camera.zoom=Math.max(.65,camera.zoom/1.25);camera.updateProjectionMatrix();};$('reset-camera').onclick=()=>setMode(mode);$('clear-selection').onclick=()=>{selected=null;$('selection').hidden=true;selectionRing.visible=false;};$('hit-melee').onclick=()=>hitCrystal(4);$('hit-ranged').onclick=()=>hitCrystal(3);$('restore').onclick=()=>{if(selected?.userData.crystal===undefined)return;const c=crystals[selected.userData.crystal];c.hp=24;c.go.visible=true;c.go.userData.animator?.play('Spawn',true);c.spawnedAt=clock;updateCrystal();};$('show-renders').onclick=()=>{$('error').hidden=true;setMode('renders');};
 let down=null;$('scene').addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});$('scene').addEventListener('pointerup',e=>{if(!ready||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>7)return;const p=new THREE.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(p,camera);const hits=ray.intersectObjects((mode==='creatures'?galleryActors:mode==='minions'?minionActors:mapActors).children,true);for(const hit of hits){let object=hit.object;while(object&&object!==scene&&!object.userData.info)object=object.parent;if(object?.userData.info){select(object);return;}}});window.addEventListener('resize',()=>ready&&resize());if(matchMedia('(pointer:coarse)').matches)$('help').textContent='Пальцем — вращение · Двумя пальцами — масштаб и перемещение · Нажми на существо';if(innerWidth<700)document.body.classList.add('panel-hidden');}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.1,(now-lastTime)/1000||0);lastTime=now;clock+=dt;if(tween){const t=Math.min(1,(now-tween.start)/850),v=t*t*(3-2*t);camera.position.lerpVectors(tween.positionFrom,tween.positionTo,v);controls.target.lerpVectors(tween.targetFrom,tween.targetTo,v);camera.zoom=THREE.MathUtils.lerp(tween.zoomFrom,tween.zoomTo,v);camera.updateProjectionMatrix();if(t===1)tween=null;}controls.update();timeUniform.value=clock;animateRiver();updateAmbient();updateWaves();for(const m of mixers)if(m.go.parent?.visible)m.animator.update(dt);for(const group of [mapActors,galleryActors])if(group.visible)for(const go of group.children)if(go.userData.living&&!go.userData.animator){go.position.y=go.userData.originY+Math.sin(clock*(go.userData.floating?1.6:2.2)+go.userData.phase)*(go.userData.floating?.15:.025);}updateCrystalAnimations();updateBridges();updateNotice();updateCrystal();for(const item of labels){const shown=showLabels&&item.group===mode,p=item.p.clone().project(camera);item.element.style.display=shown&&p.z>-1&&p.z<1?'block':'none';item.element.style.left=`${(p.x*.5+.5)*innerWidth}px`;item.element.style.top=`${(-p.y*.5+.5)*innerHeight}px`;}if(mode!=='renders')renderer.render(scene,camera);}
async function start(){setupUI();try{const [manifest,data]=await Promise.all([fetch('manifest.json',{cache:'no-store'}).then(r=>r.json()),fetch('layout.json',{cache:'no-store'}).then(r=>r.json())]);layout=data;ambientData=await fetch('ambient.json',{cache:'no-store'}).then(r=>r.json());const textureLoader=new THREE.TextureLoader();await Promise.all(manifest.Materials.map(async spec=>{const texture=await textureLoader.loadAsync('textures/'+spec.Texture+'.png?v=0.6');texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=texture.wrapT=THREE.RepeatWrapping;texture.anisotropy=8;const material=new THREE.MeshStandardMaterial({color:0xffffff,map:texture,vertexColors:true,roughness:['Water','SkyWater'].includes(spec.Name)?.18:spec.Name==='Metal'?.32:spec.Name==='Crystal'?.25:.83,metalness:spec.Name==='Metal'?.4:spec.Name==='Crystal'?.1:0,side:THREE.DoubleSide,emissive:spec.Emission?0xffffff:0,emissiveMap:spec.Emission?texture:null,emissiveIntensity:spec.Emission*.55});material.onBeforeCompile=shader=>{shader.uniforms.uValleyTime=timeUniform;shader.vertexShader='uniform float uValleyTime;\n'+shader.vertexShader;shader.fragmentShader='uniform float uValleyTime;\n'+shader.fragmentShader;if(spec.Emission)shader.fragmentShader=shader.fragmentShader.replace('#include <emissivemap_fragment>','#include <emissivemap_fragment>\n totalEmissiveRadiance *= vColor.rgb;');if(['Water','SkyWater'].includes(spec.Name)){shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n transformed.y += sin(uv.y*9.0-uValleyTime*2.1)*0.018;');shader.fragmentShader=shader.fragmentShader.replace('#include <opaque_fragment>','float shore=smoothstep(0.43,0.5,abs(fract(vMapUv.x)-0.5));float lace=smoothstep(0.55,0.95,sin(vMapUv.y*15.0-uValleyTime*3.0)*0.5+0.5);outgoingLight+=vec3(0.45,0.85,0.8)*shore*lace*0.35;\n#include <opaque_fragment>');}if(spec.Name==='Foliage')shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n transformed.x += sin(uValleyTime*1.3+position.x*0.43+position.z*0.25)*0.065*clamp(position.y*0.16,0.0,1.0);');};material.customProgramCacheKey=()=>"Valley06:"+spec.Name;palette.set(spec.Name,material);}));
 let loaded=0;const queue=[...manifest.Models];async function worker(){while(queue.length){const model=queue.shift(),group=model.WebFiles?await readModelParts(model.WebFiles):await readModel(model.WebFile);prototypes.set(model.Name,group);loaded++;$('load-progress').style.width=`${loaded/manifest.Models.length*100}%`;$('loading-status').textContent=`Сцена и существа · ${loaded} / ${manifest.Models.length}`;}}await Promise.all([worker(),worker(),worker()]);renderer=new THREE.WebGLRenderer({canvas:$('scene'),antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;scene=new THREE.Scene();scene.background=new THREE.Color(0x18363d);scene.fog=new THREE.Fog(0x18363d,230,540);camera=new THREE.OrthographicCamera(-90,90,60,-60,.1,700);camera.position.set(0,140,98);controls=new OrbitControls(camera,$('scene'));controls.enableDamping=true;controls.dampingFactor=.075;controls.minPolarAngle=.12;controls.maxPolarAngle=1.35;controls.minZoom=.65;controls.maxZoom=12;controls.addEventListener('start',()=>tween=null);scene.add(new THREE.HemisphereLight(0xc7dfdc,0x48653b,1.4));const sun=new THREE.DirectionalLight(0xffe3ac,2.3);sun.position.set(-40,95,35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-85;sun.shadow.camera.right=85;sun.shadow.camera.top=85;sun.shadow.camera.bottom=-85;sun.shadow.camera.near=1;sun.shadow.camera.far=250;sun.shadow.normalBias=.05;sun.shadow.bias=-.00015;scene.add(sun);sunLight=sun;setQuality(quality);build();resize();ready=true;$('loading').hidden=true;setMode(wantedMode);requestAnimationFrame(frame);}catch(error){console.error(error);$('loading').hidden=true;$('error').hidden=false;}}
start();
